/* Visual explanation of the proposal. Paths are illustrations, not diagnoses. */
const OPENING_MAP = [
 ['sources','Dữ liệu dạy điều gì?','Mẫu robot đích có hình ảnh, trạng thái và hành động điều khiển. Human egocentric bổ sung tín hiệu thị giác / thao tác theo recipe. Synthetic có action labels khi quỹ đạo được thực thi thành công và binding phù hợp; video sinh đơn thuần chưa đủ.'],
 ['learning','Từ dữ liệu đến kỹ năng','VLM mã hóa hình ảnh và câu lệnh thành biểu diễn; Action Expert dùng biểu diễn cùng trạng thái để dự đoán chuỗi hành động. Chọn module cập nhật theo loss, nhãn hợp lệ và phép kiểm; video người chưa tự là nhãn robot.'],
 ['robot','Kỹ năng đi vào robot thế nào?','Camera + trạng thái + câu lệnh → mô hình dự đoán hành động → bộ điều khiển thực thi. Bộ chấm độc lập ghi kết quả.'],
 ['improve','Lỗi trở thành thông tin cho vòng tiếp theo','Chấm bước đã thử/chưa thử/chưa rõ; kiểm hệ thống và đầu vào bước. Kỹ sư chọn repair / dữ liệu / update / defer. Nếu fail từ đầu: kiểm expert feasibility / hệ thống, rồi seed và curriculum trong budget; không mặc định thêm nguồn hay training vô hạn. Học với dữ liệu cũ rồi kiểm cả task.']
];
function openingEvidence(){return `<section class="idea-delivery opening-evidence"><div class="section-head"><h2>Từ lỗi nhìn thấy đến bằng chứng để sửa</h2><p>Ví dụ rơi vật: nơi lỗi biểu hiện chưa chắc là nơi cần training. Lưu đủ dấu vết và kiểm từng giả thuyết.</p></div>
 ${openingTraceFlow()}
 <div class="idea-output-grid"><article><span>01 · QUAN SÁT</span><h3>Vật rơi lúc chuyển</h3><p>Đối chiếu thời điểm vật rời bộ gắp với action, command và response. Giữ cả context tiếp cận → gắp → nâng.</p></article><article><span>02 · GIẢ THUYẾT</span><h3>Gắp, chuyển hay điều khiển?</h3><p>Pose gắp có thể chưa tốt; action có thể sai; command có thể bị đổi hoặc robot chưa theo được. Chưa kết luận module nào sai từ một video.</p></article><article><span>03 · PHÉP KIỂM</span><h3>Đổi một yếu tố để phân biệt</h3><p>Kiểm binding trước. So bước chuyển từ pose gắp chuẩn và pose policy tự tạo; dùng kết quả để chọn sửa hệ thống hay thu correction đúng đoạn.</p></article></div>
 <details class="opening-more"><summary>VLM, Action Expert và latent: cần kiểm những gì?<span>Dấu vết phải có nguồn; biểu diễn nội bộ chưa tự là lời giải thích nguyên nhân.</span></summary><div class="opening-map-detail">
 <p><strong>VLM:</strong> lưu input và trạng thái preprocessing; ghi output representation, shape, masks và phiên bản qua adapter của model. Chỉ ghi text / grounding nếu model thực sự xuất chúng; không tự tạo “ý định” rồi coi là output thật.</p>
 <p><strong>Action Expert:</strong> lưu input conditioning, action chunk cuối của inference, horizon, normalization và units; đối chiếu với command đã gửi, timing và robot response. Ranh giới cụ thể phụ thuộc checkpoint. Với flow matching, vector field trong training khác action chunk cuối của inference; không so chúng như cùng một lệnh điều khiển.</p>
 <p><strong>Latent:</strong> kiểm finite / masks / phân bố; probe có nhãn hoặc can thiệp có kiểm soát trên dữ liệu development để kiểm giả thuyết. Probe đọc được tín hiệu không chứng minh nguyên nhân; attention hay tensor đơn lẻ cũng chưa đủ. Không truy cập được module thì ghi rõ chưa quan sát được.</p>
 <p><strong>Human bridge:</strong> common wrist motion là candidate cho motor pilot: human và robot có target cùng frame/timing, shared Action Expert trunk và native robot action head riêng. Hai nhánh R_common / R_common + H cùng freeze VLM. Thiếu geometry/timing thì không mở motion loss; transfer phải đo trên robot.</p>
 <p><strong>Training:</strong> khóa loss và module train / freeze theo recipe đã hỗ trợ; kiểm gradient, checkpoint và reload. Không có quy tắc “lỗi nhìn thì chỉ train VLM, lỗi động tác thì chỉ train Action Expert”. Action loss có thể backprop qua cả VLM / interface và Action Expert theo modules được mở; không bắt buộc hai training độc lập. Quyết định cần phép thử rồi rollout kiểm lại cả task.</p>
 <a href="#learning">Đọc cơ chế học →</a> · <a href="#architecture">Xem contracts và luồng hệ thống →</a>
 </div></details></section>`;}
function openingArrow(label){return `<div class="opening-arrow" aria-hidden="true"><span>${label}</span><svg viewBox="0 0 60 24"><path d="M2 12H54M45 4L54 12 45 20"/></svg></div>`;}
function openingArchitecture(){return `<section class="opening-map" aria-labelledby="opening-map-title">
 <header><div><span class="opening-kicker">KIẾN TRÚC GIẢI PHÁP</span><h2 id="opening-map-title">Dữ liệu → kỹ năng → robot.<br><span>Kết quả quay lại để cải thiện.</span></h2></div><button type="button" id="opening-map-play" aria-pressed="false">▶ Xem đường dữ liệu</button></header>
 <div class="opening-map-main">
  <div class="opening-sources opening-map-node" data-map-node="sources"><button type="button" class="opening-node-title" data-opening-node="sources"><span>01</span> Dữ liệu thao tác</button><div class="opening-source-pair">
   <figure><img src="assets/story/human-demo.png" alt="Người làm mẫu nhiệm vụ gắp đặt, hình minh họa." width="1672" height="941"><figcaption><strong>Human egocentric</strong><span>Thị giác / motion có nhãn và masks</span></figcaption></figure>
   <figure><img src="assets/story/task-start.png" alt="Robot đích và nhiệm vụ gắp đặt, hình minh họa." width="1672" height="941"><figcaption><strong>Mẫu robot đích</strong><span>Trạng thái + hành động</span></figcaption></figure>
  </div><div class="opening-optional"><span><b>Synthetic</b> · mở rộng tình huống</span><strong>Quỹ đạo thực thi → QA → action labels</strong><strong>Video sinh ≠ action robot đo được</strong></div></div>
  ${openingArrow('Dữ liệu hợp lệ')}
  <div class="opening-learning opening-map-node" data-map-node="learning"><button type="button" class="opening-node-title" data-opening-node="learning"><span>02</span> Học kỹ năng</button><div class="opening-model"><div class="opening-model-symbol" aria-hidden="true"><svg viewBox="0 0 100 60"><path d="M18 14L50 30 82 14M18 46L50 30 82 46M50 5V55"/><circle cx="18" cy="14" r="5"/><circle cx="18" cy="46" r="5"/><circle cx="50" cy="30" r="8"/><circle cx="82" cy="14" r="5"/><circle cx="82" cy="46" r="5"/><circle cx="50" cy="5" r="4"/><circle cx="50" cy="55" r="4"/></svg></div><strong>Pretrained VLA</strong><span>FluxVLA · GR00T N1.5 · cần kiểm tương thích</span><div class="opening-model-roles"><span><b>VLM</b> · Hình ảnh + câu lệnh → biểu diễn</span><span><b>Action Expert</b> · Biểu diễn + state → hành động</span></div></div></div>
  ${openingArrow('Gói kỹ năng')}
  <div class="opening-robot opening-map-node" data-map-node="robot"><button type="button" class="opening-node-title" data-opening-node="robot"><span>03</span> Robot thực hiện</button><figure><img src="assets/story/task-start.png" alt="Humanoid chuẩn bị đặt linh kiện vàng vào ô A1, hình minh họa." width="1672" height="941"><figcaption><strong>“Đặt linh kiện vào ô A1.”</strong><span>Camera + trạng thái + câu lệnh</span></figcaption></figure><div class="opening-runtime">Mô hình → hành động → bộ điều khiển</div></div>
 </div>
 <div class="opening-feedback opening-map-node" data-map-node="improve"><div class="opening-feedback-start"><span class="opening-return" aria-hidden="true">↶</span><div><strong>Chưa đạt yêu cầu?</strong><span>Ghi kết quả và dấu vết</span></div></div><div class="opening-feedback-route"><span>Chấm bước & kiểm nguyên nhân</span><b aria-hidden="true">→</b><span>Sửa / dữ liệu / tạm dừng</span><b aria-hidden="true">→</b><span>Học / đo task</span></div><button type="button" data-opening-case>Xem một tình huống lỗi ↗</button></div>
 <div class="opening-ownership"><span>Phần đội đề xuất xây</span><strong>Adapters · QA · nguồn gốc dữ liệu</strong><strong>Trace · recipe · đo chất lượng / tổng công</strong><small>Kỹ sư duyệt quyết định</small></div>
 <div class="opening-map-detail" aria-live="polite"><strong id="opening-map-detail-title">Một vòng phát triển kỹ năng, có người kiểm.</strong><p id="opening-map-detail-body">Mỗi nguồn vào đúng loss / module qua recipe đã kiểm; common wrist bridge là candidate cần kiểm. Khi fail: ghi bằng chứng, kiểm giả thuyết, kỹ sư chọn sửa / dữ liệu / tạm dừng. Kiểm toàn task và điều kiện đang tốt; khóa model rồi final giữ riêng.</p></div>
 <p class="opening-proposal-note">Thiết kế VLA đề xuất · Ảnh / demo minh họa · Chưa rollout VLA trên GR1 của đội</p>
 </section>`;}
function openingIntro(){return `<header class="opening-intro"><span class="opening-kicker">01 · Ý TƯỞNG & VẤN ĐỀ</span><h1>Phát triển kỹ năng humanoid. <em>Dữ liệu đúng, bằng chứng rõ.</em></h1><p>Tận dụng pretrained VLA, mẫu robot đích, human egocentric video và synthetic data để giảm công phát triển kỹ năng ở cùng chất lượng. Pipeline nối dữ liệu đã kiểm → training → rollout → bằng chứng → cải thiện → gói kỹ năng có thể tái lập.</p><div class="opening-problem"><span>VẤN ĐỀ</span><p>Thu mẫu robot tốn công vận hành, reset và kiểm dữ liệu. Human video không tự có action robot; synthetic chỉ hữu ích khi nhãn và binding hợp lệ. <strong>Làm sao tận dụng đúng từng nguồn, sửa đúng chỗ và chứng minh tổng công giảm?</strong></p></div></header>`;}
function openingCase(){return `<section class="opening-case" id="opening-case" aria-labelledby="opening-case-title"><header><span class="opening-kicker">VÍ DỤ XUYÊN SUỐT</span><h2 id="opening-case-title">Khi robot làm sai,<br>giải pháp giúp đội xử lý thế nào?</h2><p>Cùng nhiệm vụ đặt linh kiện vàng vào ô A1. Chọn một tình huống để xem đường cải thiện.</p></header><div class="opening-condition-tabs" role="group" aria-label="Chọn tình huống minh họa">${['contact','visual'].map(id=>[id,IDEA_CONDITIONS[id]]).map(([id,c])=>`<button type="button" data-idea-condition="${id}" aria-pressed="${id==='contact'}"><span>0${id==='contact'?1:2}</span>${c.label}</button>`).join('')}</div><div id="opening-case-body"></div></section>`;}
function openingMotion(){return `<div class="opening-motion" hidden><svg viewBox="0 0 640 360" role="img" aria-label="Sơ đồ chuyển động nhìn từ trên: tay robot, linh kiện và khay A1"><defs><pattern id="opening-grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#e5ebf3" stroke-width=".7"/></pattern></defs><rect width="640" height="360" fill="#f6f8fc"/><rect x="40" y="112" width="560" height="225" rx="12" fill="url(#opening-grid)" stroke="#cdd7e5"/><text x="25" y="28" fill="#526b8b" font-size="11" font-family="Arial,sans-serif">CHUYỂN ĐỘNG MINH HỌA 2D · NHÌN TỪ TRÊN</text><rect x="254" y="46" width="62" height="50" rx="14" fill="#d6dfeb" stroke="#b3c1d5"/><circle cx="285" cy="100" r="15" fill="#fff" stroke="#8095b3" stroke-width="4"/><text x="340" y="70" fill="#7085a1" font-size="12" font-family="Arial,sans-serif">Tay robot</text><rect x="433" y="214" width="142" height="106" rx="7" fill="#dfe6f0" stroke="#aebed3"/><path d="M480 214V320M527 214V320M433 267H575" stroke="#aebed3"/><rect x="437" y="271" width="39" height="44" rx="4" fill="#e5f2eb" stroke="#67a17b" stroke-width="2"/><text x="447" y="299" fill="#36744e" font-size="13" font-family="Arial,sans-serif">A1</text><text x="435" y="197" fill="#526b8b" font-size="12" font-family="Arial,sans-serif">Ô đích</text><path class="opening-arm" fill="none" stroke="#7b90af" stroke-width="19" stroke-linecap="round" stroke-linejoin="round"/><path class="opening-arm-inner" fill="none" stroke="#dfe7f2" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/><circle class="opening-elbow" r="11" fill="#fff" stroke="#8095b3" stroke-width="3"/><g class="opening-part"><rect x="-14" y="-9" width="28" height="18" rx="2" fill="#e9ba32" stroke="#bf9223"/><path d="M-14-9L-7-15H20L14-9" fill="#f3cf5c" stroke="#bf9223" stroke-width=".6"/></g><g class="opening-gripper"><circle cy="-7" r="8" fill="#fff" stroke="#8193ab" stroke-width="3"/><path class="opening-fingers" fill="none" stroke="#344b68" stroke-width="5" stroke-linecap="round"/></g><text class="opening-motion-state" x="25" y="350" fill="#526b8b" font-size="12" font-family="Arial,sans-serif">Tiếp cận linh kiện</text></svg></div>`;}
function openingCaseBody(condition,health){const c=IDEA_CONDITIONS[condition],repair=health==='repair',pending=health==='pending';return `<div class="opening-case-grid"><figure class="opening-failure-view"><div class="opening-failure-image"><img src="assets/story/${c.image}" alt="${esc(c.observation)} Hình dựng để giải thích tình huống." width="1672" height="941" decoding="sync"><span class="opening-image-tag">TÌNH HUỐNG MINH HỌA</span><span class="opening-object-mark ${condition}" aria-hidden="true"></span><span class="opening-observation-label ${condition}">${condition==='visual'?'Vật vẫn trên bàn':'Vật tuột khỏi bộ gắp'}</span></div><figcaption><span>QUAN SÁT ĐƯỢC</span><h3>${c.failure}</h3><p>${condition==='visual'?'Gắp hụt trong điều kiện ánh sáng khác. Chưa biết nguyên nhân nằm ở camera, điều khiển hay dữ liệu học.':'Robot đã nâng vật nhưng không giữ được vật đến khay. Cần kiểm bộ gắp và điều khiển tiếp xúc.'}</p></figcaption></figure>
 <div class="opening-response"><div class="opening-response-row"><span>01</span><div><h3>Lưu thông tin của lượt lỗi</h3><p>Lưu ảnh / câu lệnh / state đầu vào, biểu diễn model khi adapter cho phép, action dự đoán, command đã gửi và response đo được. Căn thời gian để tìm điểm lệch đầu tiên.</p></div></div><div class="opening-response-row"><span>02</span><div><h3>Kỹ sư kiểm trước khi chọn dữ liệu</h3><ul>${c.checks.map(x=>`<li>${x}</li>`).join('')}</ul></div></div><fieldset class="opening-health-choice"><legend>Trạng thái và nhánh giả định</legend><button type="button" data-opening-health="pending" aria-pressed="${pending}">Chưa có phép kiểm</button><button type="button" data-opening-health="repair" aria-pressed="${repair}">Có lỗi hệ thống</button><button type="button" data-opening-health="data" aria-pressed="${health==='data'}">Đã kiểm, xét dữ liệu</button></fieldset><div class="opening-response-row opening-chosen"><span>03</span><div><span class="opening-assumption">${pending?'CHƯA CHỌN CAN THIỆP':repair?'GIẢ ĐỊNH: CÓ LỖI HỆ THỐNG':'GIẢ ĐỊNH: ĐÃ KIỂM HỆ THỐNG'}</span><h3>${pending?'Cần phép kiểm phân biệt nguyên nhân':repair?'Sửa cấu hình / điều khiển, rồi thử lại':c.choice}</h3><p>${pending?(condition==='visual'?'Kiểm camera, calibration và timing; so cùng hình học ở ánh sáng gốc / ánh sáng mới. Dùng trace để kiểm giả thuyết coverage; chưa đủ bằng chứng thì hoãn, không tự mở training.':'So chuyển vật từ pose gắp chuẩn và pose policy tự tạo, sau khi kiểm mapping và controller. Chưa đủ bằng chứng thì kỹ sư hoãn quyết định; không tự mở training.'):repair?'Lập lại kết quả ban đầu sau khi sửa. Chưa quy lỗi cho dữ liệu học.':condition==='visual'?'Thử gói biến thể ánh sáng nhỏ trên dữ liệu hợp lệ; giữ nhãn hành động khi hình học và ý nghĩa thao tác không đổi.':'Ưu tiên mẫu robot đích về giữ và chuyển vật. Kiểm pose gắp do bước trước tạo ra; giữ context gắp–chuyển trong correction. Video người đơn thuần chưa đủ nhãn tiếp xúc.'}</p></div></div></div></div>
 <div class="opening-intervention-path" aria-label="Phép kiểm hoặc các bước can thiệp">${(pending?['Căn thời gian trace','Kiểm binding / controller','Kiểm context gắp–chuyển','Duyệt can thiệp hoặc hoãn']:repair?['Sửa hệ thống','Lập lại baseline','Đo lại theo điều kiện','Chọn bước tiếp theo']:['Kỹ sư duyệt gói','Kiểm dữ liệu & nhãn','Huấn luyện phiên bản mới','Đo lại với đối chứng']).map((x,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><strong>${x}</strong></div>`).join('')}</div>
 <div class="opening-outcome"><img src="assets/story/task-success.png" alt="Kết quả đặt đúng ô kỳ vọng, hình minh họa." width="1672" height="941"><div><span>KẾT QUẢ CẦN KIỂM CHỨNG</span><h3>Đặt đúng chưa đủ. Cần đo cả chất lượng và tổng công.</h3><p>Kiểm lại bước yếu, chuyển tiếp, toàn task và các điều kiện trước đó đã tốt. Khóa model rồi thử trên tập giữ riêng; so chất lượng và tổng công với thu mẫu robot có chủ đích. Một lượt sửa đúng chưa đủ để nhận cải thiện.</p></div></div><button type="button" class="improvement-jump" data-opening-improvement>Xem từ lỗi → kế hoạch thu và training ↓</button>`;}
function initIdeaOpening(signal){const root=document.querySelector('.idea-overview');if(!root)return;let condition='contact',health='pending',mapIndex=-1,timer=null,playing=false,motionFrame=null,demoController=null;const play=root.querySelector('#opening-map-play');
 function mapStop(){clearTimeout(timer);timer=null;playing=false;play.textContent='▶ Xem đường dữ liệu';play.setAttribute('aria-pressed','false');}
 function mapSelect(i){mapIndex=i;const [id,title,body]=OPENING_MAP[i];root.querySelectorAll('[data-map-node]').forEach(el=>el.classList.toggle('is-active',el.dataset.mapNode===id));root.querySelectorAll('[data-opening-node]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.openingNode===id)));root.querySelector('#opening-map-detail-title').textContent=title;root.querySelector('#opening-map-detail-body').textContent=body;}
 function mapTick(){if(!playing||signal.aborted)return;if(mapIndex===3){mapStop();return;}mapSelect(mapIndex+1);timer=setTimeout(mapTick,4500);}
 function motionStop(){cancelAnimationFrame(motionFrame);motionFrame=null;}
 function renderCase(){motionStop();demoController?.dispose();root.querySelector('#opening-case-body').innerHTML=openingCaseBody(condition,health);const image=root.querySelector('.opening-failure-image'),figure=root.querySelector('.opening-failure-view');image.insertAdjacentHTML('beforeend',openingMotion()+'<button type="button" class="opening-motion-play" data-opening-motion>▶ Xem chuyển động minh họa 2D</button>'+humanoidDemoMarkup());image.insertAdjacentHTML('afterend',humanoidDemoControls());demoController=initHumanoidDemo(figure,condition,health,signal,s=>{root.querySelectorAll('.opening-response-row').forEach((row,i)=>row.classList.toggle('demo-active',s===i+2));root.querySelector('.opening-intervention-path').classList.toggle('demo-active',s===5);});}
 function motionStart(){mapStop();motionStop();const area=root.querySelector('.opening-motion'),button=root.querySelector('[data-opening-motion]');area.hidden=false;button.textContent='↺ Phát lại chuyển động';const start=performance.now(),duration=6000,arm=area.querySelector('.opening-arm'),inner=area.querySelector('.opening-arm-inner'),elbow=area.querySelector('.opening-elbow'),gripper=area.querySelector('.opening-gripper'),fingers=area.querySelector('.opening-fingers'),part=area.querySelector('.opening-part'),label=area.querySelector('.opening-motion-state');const mix=(a,b,t)=>a+(b-a)*t,clamp=x=>Math.min(1,Math.max(0,x)),ease=x=>x*x*(3-2*x);
  function frame(now){if(signal.aborted)return;let p=clamp((now-start)/duration);if(matchMedia('(prefers-reduced-motion: reduce)').matches)p=1;const grasp=condition==='visual'?145:180,approach=ease(clamp(p/.28)),travel=ease(clamp((p-.45)/.42));const x=p<.45?mix(260,grasp,approach):mix(grasp,460,travel),y=p<.45?mix(160,272,approach):mix(272,287,travel);const dx=x-285,dy=y-100,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-Math.acos(Math.max(-1,Math.min(1,(140*140+d*d-160*160)/(280*d))));const ex=285+140*Math.cos(a),ey=100+140*Math.sin(a),path=`M285 100L${ex} ${ey}L${x} ${y}`;arm.setAttribute('d',path);inner.setAttribute('d',path);elbow.setAttribute('cx',ex);elbow.setAttribute('cy',ey);gripper.setAttribute('transform',`translate(${x} ${y})`);const gap=mix(22,8,ease(clamp((p-.28)/.14)));fingers.setAttribute('d',`M${-gap} 0V21H${-gap+5}M${gap} 0V21H${gap-5}`);let px=180,py=285,angle=0;if(condition==='contact'&&p>.42){if(p<.65){px=x;py=y+13;}else{px=303;py=mix(293,317,ease(clamp((p-.65)/.16)));angle=23;}}part.setAttribute('transform',`translate(${px} ${py}) rotate(${angle})`);label.textContent=p<.28?'Tiếp cận linh kiện':p<.45?'Đóng bộ gắp':p<.87?(condition==='visual'?'Bộ gắp rời đi; vật vẫn ở trên bàn':p<.65?'Nâng và chuyển vật':'Linh kiện tuột khỏi bộ gắp'):'Không hoàn thành → ghi lượt lỗi, kiểm hệ thống';if(p<1)motionFrame=requestAnimationFrame(frame);else{motionFrame=null;button.textContent='↺ Phát lại chuyển động';}}
  motionFrame=requestAnimationFrame(frame);
 }
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.ideaCondition){condition=b.dataset.ideaCondition;health='pending';renderCase();}
  if(b.dataset.openingHealth){health=b.dataset.openingHealth;renderCase();}
  if(b.hasAttribute('data-opening-motion'))motionStart();
  if(b.hasAttribute('data-opening-improvement')){mapStop();demoController?.pause();root.querySelector('#task-improvement').closest('details').open=true;root.querySelector('#task-improvement').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
  if(b.dataset.openingNode){mapStop();mapSelect(OPENING_MAP.findIndex(x=>x[0]===b.dataset.openingNode));}
  if(b.id==='opening-map-play'){if(playing){mapStop();return;}motionStop();demoController?.pause();playing=true;mapSelect(0);play.textContent='Ⅱ Tạm dừng';play.setAttribute('aria-pressed','true');timer=setTimeout(mapTick,4500);}
  if(b.hasAttribute('data-opening-case')){mapStop();root.querySelector('#opening-case').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
  if(b.classList.contains('humanoid-play'))mapStop();
 },{signal});document.addEventListener('visibilitychange',()=>{if(document.hidden){mapStop();motionStop();}},{signal});root.querySelector('#idea-play').addEventListener('click',()=>{mapStop();motionStop();demoController?.pause();},{signal});root.querySelector('#idea-film').addEventListener('play',()=>{mapStop();motionStop();demoController?.pause();},{signal});signal.addEventListener('abort',()=>{mapStop();motionStop();demoController?.dispose();},{once:true});renderCase();initSkillPlan(signal);
}
